  var norm = function (s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); };

  // ---------- dictionaries ----------
  var custom = {};
  try { custom = JSON.parse(localStorage.getItem(CUSTOM_KEY) || '{}') || {}; } catch (e) { custom = {}; }
  var customPhrases = [];
  function buildCustomPhrases() {
    customPhrases = Object.keys(custom).filter(function (k) { return k.length >= 4; })
      .sort(function (a, b) { return b.length - a.length; })
      .map(function (k) { return [k, custom[k]]; });
  }
  buildCustomPhrases();
